impl<M> Message for Box<M>
where
    M: Message,
{
    fn encode_raw(&self, buf: &mut impl BufMut) {
        (**self).encode_raw(buf)
    }
    fn poll_encode_raw<S>(
        &self,
        target: &mut S,
        state: &mut PollEncodeState<S>,
        cx: &mut Context<'_>,
    ) -> Poll<Result<(), S::Error>>
    where
        Self: Sized,
        S: AsyncEncodeTarget + Send,
    {
        (**self).poll_encode_raw(target, state, cx)
    }
    fn merge_field(
        &mut self,
        tag: u32,
        wire_type: WireType,
        buf: &mut impl Buf,
        ctx: DecodeContext,
    ) -> Result<(), DecodeError> {
        (**self).merge_field(tag, wire_type, buf, ctx)
    }
    fn encoded_len(&self) -> usize {
        (**self).encoded_len()
    }
    fn clear(&mut self) {
        (**self).clear()
    }
}

